"""Execution of a physical plan over one or two in-memory tables.

The executor is deliberately separate from the planner: the same logical query can be executed through
different physical plans, and the reconciliation command exists to prove they agree. Index scans build
their index on first use and cache it on the table, so `index-scan` is a real access path rather than a
label.

Rows below a join are local to one table and keyed by plain column names. A join emits rows keyed
"table.column"; every operator above a join therefore sees qualified column references. Hash joins in
either build direction and index-nested-loop joins all canonicalise their output to (left original
position, right original position), so the physical algorithm never affects row order or content.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Iterable

from .errors import PlanError, ValidationError
from .parser import Aggregate, BoolOp, Column, Comparison, InList, IsNull, Literal, Not, Projection, Star
from .planner import (
    FullScan,
    HashJoin,
    IndexNestedLoopJoin,
    IndexScan,
    PhysicalAggregate,
    PhysicalFilter,
    PhysicalLimit,
    PhysicalProject,
    PhysicalSort,
)


@dataclass(slots=True)
class Table:
    name: str
    columns: tuple[str, ...]
    rows: list[dict[str, object]] = field(default_factory=list)
    _indexes: dict[str, dict[object, list[int]]] = field(default_factory=dict, init=False)

    def index_for(self, column: str) -> dict[object, list[int]]:
        """Built once per column and reused; the planner is told which columns have one."""
        if column not in self.columns:
            raise ValidationError(f"no such column to index: {column}", table=self.name)
        if column not in self._indexes:
            table: dict[object, list[int]] = {}
            for position, row in enumerate(self.rows):
                table.setdefault(row.get(column), []).append(position)
            self._indexes[column] = table
        return self._indexes[column]


def _row_key(column: Column) -> str:
    return f"{column.table}.{column.name}" if column.table is not None else column.name


def evaluate(node: object, row: dict[str, object]) -> object:
    """Evaluate a scalar or predicate expression against one row.

    Below a join rows use plain column names; above a join they use "table.column" and the Column node
    carries that table.
    """
    if isinstance(node, Literal):
        return node.value
    if isinstance(node, Column):
        key = _row_key(node)
        if key not in row and node.table is not None and node.name in row:
            key = node.name  # a localized predicate evaluated on local rows
        if key not in row:
            raise PlanError(f"column not present in row: {key}", known=sorted(row))
        return row[key]
    if isinstance(node, Comparison):
        left, right = evaluate(node.left, row), evaluate(node.right, row)
        if left is None or right is None:
            return None
        try:
            return {
                "=": lambda: left == right,
                "<>": lambda: left != right,
                "<": lambda: left < right,
                "<=": lambda: left <= right,
                ">": lambda: left > right,
                ">=": lambda: left >= right,
            }[node.operator]()
        except TypeError:
            return None
    if isinstance(node, InList):
        value = evaluate(node.operand, row)
        if value is None:
            return None
        hit = any(value == evaluate(candidate, row) for candidate in node.values)
        return (not hit) if node.negated else hit
    if isinstance(node, IsNull):
        missing = evaluate(node.operand, row) is None
        return (not missing) if node.negated else missing
    if isinstance(node, Not):
        inner = evaluate(node.operand, row)
        return None if inner is None else (not inner)
    if isinstance(node, BoolOp):
        values = [evaluate(operand, row) for operand in node.operands]
        if node.operator == "and":
            if any(value is False for value in values):
                return False
            return None if any(value is None for value in values) else True
        if any(value is True for value in values):
            return True
        return None if any(value is None for value in values) else False
    raise ValidationError(f"cannot evaluate expression: {type(node).__name__}")


def _truthy(value: object) -> bool:
    return value is True


def aggregate_value(function: str, values: list[object], distinct: bool) -> object:
    if distinct:
        seen: list[object] = []
        for value in values:
            if value not in seen:
                seen.append(value)
        values = seen
    present = [value for value in values if value is not None]
    if function == "count":
        return len(present)
    if not present:
        return None
    numbers = [float(value) for value in present]  # type: ignore[arg-type]
    if function == "sum":
        return sum(numbers)
    if function == "min":
        return min(numbers)
    if function == "max":
        return max(numbers)
    if function == "avg":
        return sum(numbers) / len(numbers)
    raise ValidationError(f"unknown aggregate: {function}")


def _projection_label(projection: Projection) -> str:
    if projection.alias:
        return projection.alias
    expression = projection.expression
    if isinstance(expression, Column):
        return expression.name
    if isinstance(expression, Aggregate):
        return _aggregate_label(expression)
    if isinstance(expression, Star):
        return "*"
    return "expression"


def execute(node: object, tables: "Table | dict[str, Table]") -> tuple[list[str], list[dict[str, object]]]:
    if isinstance(tables, Table):
        tables = {tables.name: tables}
    columns, rows, _ = _execute(node, tables)
    return columns, rows


def _execute(
    node: object, tables: "dict[str, Table]"
) -> tuple[list[str], list[dict[str, object]], list[int] | None]:
    """Internal form: scans also report each row's original position in its table."""
    if isinstance(node, FullScan):
        table = tables[node.table]
        rows = [{column: row.get(column) for column in node.columns} for row in table.rows]
        return list(node.columns), rows, list(range(len(table.rows)))
    if isinstance(node, IndexScan):
        table = tables[node.table]
        positions = list(table.index_for(node.column).get(node.value, []))
        rows = [{column: table.rows[position].get(column) for column in node.columns} for position in positions]
        return list(node.columns), rows, positions
    if isinstance(node, PhysicalFilter):
        columns, rows, positions = _execute(node.input, tables)
        if positions is None:
            return columns, [row for row in rows if _truthy(evaluate(node.predicate, row))], None
        kept = [
            (row, position)
            for row, position in zip(rows, positions)
            if _truthy(evaluate(node.predicate, row))
        ]
        return columns, [row for row, _ in kept], [position for _, position in kept]
    if isinstance(node, (HashJoin, IndexNestedLoopJoin)):
        columns, rows = _execute_join(node, tables)
        return columns, rows, None
    if isinstance(node, PhysicalAggregate):
        columns, rows, _ = _execute(node.input, tables)
        group_keys = list(node.group_by)
        names = list(node.group_labels or group_keys) + [_aggregate_label(function) for function in node.aggregates]
        groups: dict[tuple[object, ...], list[dict[str, object]]] = {}
        for row in rows:
            groups.setdefault(tuple(row.get(name) for name in group_keys), []).append(row)
        if not node.group_by and not groups:
            groups[()] = []
        output: list[dict[str, object]] = []
        for key in sorted(groups, key=lambda item: tuple((value is None, str(value)) for value in item)):
            members = groups[key]
            labels = node.group_labels or group_keys
            record: dict[str, object] = {name: value for name, value in zip(labels, key)}
            for function in node.aggregates:
                values = [_aggregate_input(function, member) for member in members]
                record[_aggregate_label(function)] = aggregate_value(function.function, values, function.distinct)
            output.append(record)
        return names, output, None
    if isinstance(node, PhysicalProject):
        columns, rows, _ = _execute(node.input, tables)
        output: list[dict[str, object]] = []
        for row in rows:
            record: dict[str, object] = {}
            for projection in node.projections:
                expression = projection.expression
                if isinstance(expression, Star):
                    record.update(row)
                elif isinstance(expression, Aggregate):
                    record[_projection_label(projection)] = row.get(_aggregate_label(expression))
                else:
                    record[_projection_label(projection)] = evaluate(expression, row)
            output.append(record)
        if node.qualified:
            # Above a join a bare star expands to the actual "table.column" output columns; an aliased
            # star is impossible in this subset so every projection is a real label.
            header = [
                _projection_label(projection)
                for projection in node.projections
                if not isinstance(projection.expression, Star)
            ]
            if any(isinstance(projection.expression, Star) for projection in node.projections):
                header = _ordered_star_keys(node.projections, rows) + header
            return header, output, None
        return [_projection_label(projection) for projection in node.projections], output, None
    if isinstance(node, PhysicalSort):
        columns, rows, _ = _execute(node.input, tables)

        def sort_key(row: dict[str, object]) -> tuple:
            key: list[object] = []
            for name, table_name, descending in node.keys:
                value = row.get(name)
                if value is None and table_name is not None:
                    value = row.get(f"{table_name}.{name}")
                key.append(_Descending(value) if descending else _Ascending(value))
            return tuple(key)

        return columns, sorted(rows, key=sort_key), None
    if isinstance(node, PhysicalLimit):
        columns, rows, _ = _execute(node.input, tables)
        return columns, rows[: node.count], None
    raise ValidationError(f"cannot execute node: {type(node).__name__}")


def _ordered_star_keys(projections: tuple[Projection, ...], rows: list[dict[str, object]]) -> list[str]:
    """Order of a SELECT * above a join.

    Join output rows are already built in (left scan columns, then right scan columns) order, so the
    first row carries the canonical column order. Falling back to first-appearance keeps this safe if
    the join produced zero rows.
    """
    if not any(isinstance(item.expression, Star) for item in projections):
        return []
    if rows:
        return list(rows[0].keys())
    names: list[str] = []
    for row in rows:
        for name in row:
            if name not in names:
                names.append(name)
    return names


def _merged_row(
    left_table: str,
    left_columns: Iterable[str],
    left_row: dict[str, object],
    right_table: str,
    right_columns: Iterable[str],
    right_row: dict[str, object],
) -> dict[str, object]:
    merged: dict[str, object] = {}
    for column in left_columns:
        merged[f"{left_table}.{column}"] = left_row.get(column)
    for column in right_columns:
        merged[f"{right_table}.{column}"] = right_row.get(column)
    return merged


def _execute_join(node: object, tables: dict[str, Table]) -> tuple[list[str], list[dict[str, object]]]:
    if isinstance(node, HashJoin):
        left_columns, left_rows, left_positions = _execute(node.left, tables)
        right_columns, right_rows, right_positions = _execute(node.right, tables)
        pairs: list[tuple[int, int, dict[str, object]]] = []
        if node.build_side == "right":
            index = _hash_by_key(right_rows, right_positions, node.right_key)
            for left_row, left_position in zip(left_rows, left_positions or []):
                for right_position, right_row in index.get(left_row.get(node.left_key), []):
                    pairs.append((left_position, right_position, _merged_row(node.left_table, left_columns, left_row, node.right_table, right_columns, right_row)))
        else:
            index = _hash_by_key(left_rows, left_positions, node.left_key)
            for right_row, right_position in zip(right_rows, right_positions or []):
                for left_position, left_row in index.get(right_row.get(node.right_key), []):
                    pairs.append((left_position, right_position, _merged_row(node.left_table, left_columns, left_row, node.right_table, right_columns, right_row)))
    elif isinstance(node, IndexNestedLoopJoin):
        outer_columns, outer_rows, outer_positions = _execute(node.outer, tables)
        inner_table = tables[node.inner_table]
        index = inner_table.index_for(node.inner_index_column)
        if node.outer_side == "left":
            pairs = _inlj_pairs(node, outer_rows, outer_positions or [], outer_columns, inner_table, index, left_outer=True)
        else:
            pairs = _inlj_pairs(node, outer_rows, outer_positions or [], outer_columns, inner_table, index, left_outer=False)
    else:  # pragma: no cover - guarded by caller
        raise ValidationError(f"cannot execute join node: {type(node).__name__}")

    # One canonical order regardless of algorithm: logical left original order, then right.
    pairs.sort(key=lambda item: (item[0], item[1]))
    columns: list[str] = []
    for _, _, row in pairs:
        for name in row:
            if name not in columns:
                columns.append(name)
    return columns, [row for _, _, row in pairs]


def _hash_by_key(rows: list[dict[str, object]], positions: list[int], key: str) -> dict[object, list[tuple[int, dict[str, object]]]]:
    table: dict[object, list[tuple[int, dict[str, object]]]] = {}
    for row, position in zip(rows, positions):
        value = row.get(key)
        if value is None:  # a null join key never matches
            continue
        table.setdefault(value, []).append((position, row))
    return table


def _inlj_pairs(
    node: IndexNestedLoopJoin,
    outer_rows: list[dict[str, object]],
    outer_positions: list[int],
    outer_columns: list[str],
    inner_table: Table,
    index: dict[object, list[int]],
    *,
    left_outer: bool,
) -> list[tuple[int, int, dict[str, object]]]:
    outer_key = node.left_key if left_outer else node.right_key
    pairs: list[tuple[int, int, dict[str, object]]] = []
    for outer_row, outer_position in zip(outer_rows, outer_positions):
        value = outer_row.get(outer_key)
        if value is None:
            continue
        for inner_position in index.get(value, []):
            inner_row_full = inner_table.rows[inner_position]
            inner_row = {column: inner_row_full.get(column) for column in node.inner_columns}
            if not all(_truthy(evaluate(predicate, inner_row)) for predicate in node.inner_predicates):
                continue
            if left_outer:
                merged = _merged_row(node.left_table, outer_columns, outer_row, node.right_table, node.inner_columns, inner_row)
                pairs.append((outer_position, inner_position, merged))
            else:
                merged = _merged_row(node.left_table, node.inner_columns, inner_row, node.right_table, outer_columns, outer_row)
                pairs.append((inner_position, outer_position, merged))
    return pairs


def _aggregate_argument(function: Aggregate) -> str:
    if isinstance(function.argument, Star):
        return "*"
    return getattr(function.argument, "name", "?")


def _aggregate_label(function: Aggregate) -> str:
    """One place decides an aggregate's output column name.

    The aggregate stage names its column and the projection stage looks that name up, so the two must
    agree by construction: a first version spelled DISTINCT in one place and not the other, and the
    projection then raised KeyError('count(DISTINCT region)').
    """
    distinct = "DISTINCT " if function.distinct else ""
    return f"{function.function}({distinct}{_aggregate_argument(function)})"


def _aggregate_input(function: Aggregate, row: dict[str, object]) -> object:
    if isinstance(function.argument, Star):
        return 1
    if isinstance(function.argument, Literal):
        return function.argument.value
    return row.get(_row_key(function.argument))


class _Ascending:
    """Sort keys: NULLs last in both directions, values compared as floats when possible."""

    __slots__ = ("value",)

    def __init__(self, value: object) -> None:
        self.value = value

    def _pair(self) -> tuple:
        return (self.value is None, 0 if isinstance(self.value, (int, float)) else 1, "" if self.value is None else str(self.value))

    def __lt__(self, other: "_Ascending") -> bool:
        left, right = self._pair(), other._pair()
        if left[0] != right[0]:
            return left[0] < right[0]
        if left[0]:
            return False
        if isinstance(self.value, (int, float)) and isinstance(other.value, (int, float)):
            return float(self.value) < float(other.value)
        return left[2] < right[2]


class _Descending(_Ascending):
    def __lt__(self, other: "_Ascending") -> bool:
        left, right = self._pair(), other._pair()
        if left[0] != right[0]:
            return left[0] < right[0]
        if left[0]:
            return False
        if isinstance(self.value, (int, float)) and isinstance(other.value, (int, float)):
            return float(self.value) > float(other.value)
        return left[2] > right[2]


def sortable(values: Iterable[object]) -> list[object]:
    return sorted(values, key=lambda value: _Ascending(value))

"""Logical rewriting and cost-based physical planning.

Pipeline: parse tree -> logical plan -> rewrites -> physical plan. The rewrites are deliberately few
and each one is observable in `explain`, because a rewrite nobody can see is a rewrite nobody can
debug:

  * predicate pushdown -- a filter is moved below the projection it feeds (never below an aggregate
    unless every referenced column is a grouping key); in a two-table plan every WHERE conjunct that
    references one input alone is pushed into that input's scan;
  * projection pruning -- a scan reads only the columns that survive to the top, per input;
  * constant folding -- comparisons between literals are decided at plan time;
  * limit pushdown -- a bounded sort keeps at most `limit` rows.

Physical selection is cost-based on the decisions that matter for this subset:

  * one table -- a filter that pins an indexed column to a literal becomes an `IndexScan`, otherwise
    the scan is full;
  * two tables -- an equality INNER JOIN is costed as hash-join building either side and, when the
    inner join key has an index, as index-nested-loop join; the cheapest physical plan wins, ties
    preferring hash-join and then the FROM-order build side.

Estimates use per-column distinct counts when the catalogue has them, and documented defaults when it
does not.
"""

from __future__ import annotations

from dataclasses import dataclass, field

from .errors import PlanError, ValidationError
from .parser import (
    Aggregate,
    BoolOp,
    Column,
    Comparison,
    InList,
    IsNull,
    JoinClause,
    Literal,
    Not,
    OrderKey,
    Projection,
    Select,
    Star,
)

# selectivity defaults, used when a column has no distinct count in the catalogue
DEFAULT_EQUALITY = 0.1
DEFAULT_RANGE = 0.3
DEFAULT_IN = 0.25
DEFAULT_IS_NULL = 0.05
DEFAULT_NOT = 0.5

SCAN_COST_PER_ROW = 1.0
INDEX_COST = 2.0
FILTER_COST_PER_ROW = 0.5
PROJECT_COST_PER_ROW = 0.2
SORT_COST_PER_ROW = 1.5
AGGREGATE_COST_PER_ROW = 0.8

# hash join: one build pass (hashing), one probe pass, plus one charge per emitted pair
HASH_BUILD_COST_PER_ROW = 0.5
HASH_PROBE_COST_PER_ROW = 0.3
JOIN_OUTPUT_COST_PER_ROW = 0.8


@dataclass(frozen=True, slots=True)
class TableInfo:
    name: str
    columns: tuple[str, ...]
    rows: int
    distinct: dict[str, int] = field(default_factory=dict)
    indexes: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if self.rows < 0:
            raise ValidationError("rows must be >= 0", value=self.rows)
        unknown = sorted(set(self.indexes) - set(self.columns))
        if unknown:
            raise ValidationError("index on unknown column", value=", ".join(unknown))

    def to_document(self) -> dict[str, object]:
        return {
            "name": self.name,
            "columns": list(self.columns),
            "rows": self.rows,
            "distinct": dict(self.distinct),
            "indexes": list(self.indexes),
        }


@dataclass(slots=True)
class Catalog:
    tables: dict[str, TableInfo] = field(default_factory=dict)

    def add(self, info: TableInfo) -> None:
        self.tables[info.name] = info

    def get(self, name: str) -> TableInfo:
        if name not in self.tables:
            raise PlanError(f"unknown table: {name}", known=sorted(self.tables))
        return self.tables[name]

    @classmethod
    def from_document(cls, document: dict[str, object]) -> "Catalog":
        catalog = cls()
        for entry in document.get("tables", []) or []:
            if not isinstance(entry, dict):
                raise ValidationError("catalogue entries must be objects")
            catalog.add(
                TableInfo(
                    name=str(entry["name"]),
                    columns=tuple(str(item) for item in entry.get("columns", [])),
                    rows=int(entry.get("rows", 0)),
                    distinct={str(key): int(value) for key, value in (entry.get("distinct") or {}).items()},
                    indexes=tuple(str(item) for item in entry.get("indexes", [])),
                )
            )
        return catalog


# -- logical nodes -------------------------------------------------------------------------------
@dataclass(frozen=True, slots=True)
class LogicalScan:
    table: str
    columns: tuple[str, ...]


@dataclass(frozen=True, slots=True)
class LogicalFilter:
    input: object
    predicate: object


@dataclass(frozen=True, slots=True)
class LogicalProject:
    input: object
    projections: tuple[Projection, ...]


@dataclass(frozen=True, slots=True)
class LogicalAggregate:
    input: object
    group_by: tuple[str, ...]
    aggregates: tuple[Aggregate, ...]


@dataclass(frozen=True, slots=True)
class LogicalSort:
    input: object
    keys: tuple[tuple[str, bool], ...]


@dataclass(frozen=True, slots=True)
class LogicalLimit:
    input: object
    count: int


@dataclass(frozen=True, slots=True)
class LogicalJoin:
    left: object
    right: object
    left_table: str
    right_table: str
    left_key: str
    right_key: str


# -- physical nodes ------------------------------------------------------------------------------
@dataclass(frozen=True, slots=True)
class FullScan:
    table: str
    columns: tuple[str, ...]
    rows: int


@dataclass(frozen=True, slots=True)
class IndexScan:
    table: str
    column: str
    value: object
    columns: tuple[str, ...]
    rows: int


@dataclass(frozen=True, slots=True)
class PhysicalFilter:
    input: object
    predicate: object
    rows: int
    qualified: bool = False


@dataclass(frozen=True, slots=True)
class PhysicalProject:
    input: object
    projections: tuple[Projection, ...]
    # True above a join: rows are keyed "table.column" and Column nodes carry their owning table.
    qualified: bool = False


@dataclass(frozen=True, slots=True)
class PhysicalAggregate:
    input: object
    group_by: tuple[str, ...]
    aggregates: tuple[Aggregate, ...]
    rows: int
    qualified: bool = False
    group_labels: tuple[str, ...] = ()


@dataclass(frozen=True, slots=True)
class PhysicalSort:
    input: object
    keys: tuple[tuple[str, str | None, bool], ...]


@dataclass(frozen=True, slots=True)
class PhysicalLimit:
    input: object
    count: int


@dataclass(frozen=True, slots=True)
class HashJoin:
    """Equi-join. `build_side` names the hashed input; the other probes."""

    left: object
    right: object
    left_table: str
    right_table: str
    left_key: str
    right_key: str
    build_side: str  # "left" | "right"
    rows: int


@dataclass(frozen=True, slots=True)
class IndexNestedLoopJoin:
    """Outer rows probe an index on the inner key. `outer_side` names the driving input.

    The inner side is never scanned: each outer row looks up `inner_index_column`, then the pushed
    inner predicates are applied to whatever the lookup returned. Cost scalars are stored explicitly
    so the cost model does not have to rediscover them.
    """

    outer: object
    left_table: str
    right_table: str
    left_key: str
    right_key: str
    outer_side: str  # "left" | "right"
    inner_table: str
    inner_columns: tuple[str, ...]
    inner_index_column: str
    inner_predicates: tuple[object, ...]
    lookups: int
    matched_rows: float
    rows: int


@dataclass(frozen=True, slots=True)
class Plan:
    statement: Select
    logical: object
    physical: object
    estimated_rows: int
    estimated_cost: float
    notes: tuple[str, ...] = ()

    def to_document(self) -> dict[str, object]:
        document: dict[str, object] = {
            "table": self.statement.table,
            "estimatedRows": self.estimated_rows,
            "estimatedCost": round(self.estimated_cost, 3),
            "notes": list(self.notes),
            "logical": describe_node(self.logical),
            "physical": describe_node(self.physical),
        }
        if self.statement.joins:
            document["tables"] = [self.statement.table, *(join.table for join in self.statement.joins)]
        return document


def describe_node(node: object) -> dict[str, object]:
    if isinstance(node, LogicalScan):
        return {"operator": "scan", "table": node.table, "columns": list(node.columns)}
    if isinstance(node, LogicalFilter):
        return {"operator": "filter", "input": describe_node(node.input), "predicate": _render_predicate(node.predicate)}
    if isinstance(node, LogicalProject):
        return {"operator": "project", "input": describe_node(node.input), "expressions": [_render_expression(item.expression) for item in node.projections]}
    if isinstance(node, LogicalAggregate):
        return {"operator": "aggregate", "input": describe_node(node.input), "groupBy": list(node.group_by), "functions": [item.function for item in node.aggregates]}
    if isinstance(node, LogicalSort):
        return {"operator": "sort", "input": describe_node(node.input), "keys": [{"column": name, "descending": descending} for name, descending in node.keys]}
    if isinstance(node, LogicalLimit):
        return {"operator": "limit", "input": describe_node(node.input), "count": node.count}
    if isinstance(node, LogicalJoin):
        return {
            "operator": "join",
            "type": "inner",
            "left": describe_node(node.left),
            "right": describe_node(node.right),
            "leftTable": node.left_table,
            "rightTable": node.right_table,
            "leftKey": node.left_key,
            "rightKey": node.right_key,
            "joinOrder": [node.left_table, node.right_table],
        }
    if isinstance(node, FullScan):
        return {"operator": "full-scan", "table": node.table, "columns": list(node.columns), "rows": node.rows}
    if isinstance(node, IndexScan):
        return {"operator": "index-scan", "table": node.table, "column": node.column, "value": node.value, "columns": list(node.columns), "rows": node.rows}
    if isinstance(node, PhysicalFilter):
        return {"operator": "filter", "input": describe_node(node.input), "predicate": _render_predicate(node.predicate), "rows": node.rows}
    if isinstance(node, PhysicalProject):
        return {"operator": "project", "input": describe_node(node.input), "expressions": [_render_expression(item.expression) for item in node.projections]}
    if isinstance(node, PhysicalAggregate):
        group_by = list(node.group_labels or node.group_by)
        return {"operator": "aggregate", "input": describe_node(node.input), "groupBy": group_by, "functions": [item.function for item in node.aggregates], "rows": node.rows}
    if isinstance(node, PhysicalSort):
        return {"operator": "sort", "input": describe_node(node.input), "keys": [_sort_key_document(name, table, descending) for name, table, descending in node.keys]}
    if isinstance(node, PhysicalLimit):
        return {"operator": "limit", "input": describe_node(node.input), "count": node.count}
    if isinstance(node, HashJoin):
        return {
            "operator": "hash-join",
            "left": describe_node(node.left),
            "right": describe_node(node.right),
            "leftTable": node.left_table,
            "rightTable": node.right_table,
            "leftKey": node.left_key,
            "rightKey": node.right_key,
            "buildSide": node.build_side,
            "joinOrder": [node.left_table, node.right_table] if node.build_side == "left" else [node.right_table, node.left_table],
            "rows": node.rows,
            "cost": round(_estimate_cost(node), 3),
        }
    if isinstance(node, IndexNestedLoopJoin):
        outer_document = describe_node(node.outer)
        inner_document = {
            "operator": "index-lookup",
            "table": node.inner_table,
            "column": node.inner_index_column,
            "columns": list(node.inner_columns),
            "rows": node.rows,
        }
        return {
            "operator": "index-nested-loop-join",
            "left": outer_document if node.outer_side == "left" else inner_document,
            "right": inner_document if node.outer_side == "left" else outer_document,
            "outer": outer_document,
            "inner": inner_document,
            "leftTable": node.left_table,
            "rightTable": node.right_table,
            "leftKey": node.left_key,
            "rightKey": node.right_key,
            "outerSide": node.outer_side,
            "joinOrder": [node.left_table, node.right_table] if node.outer_side == "left" else [node.right_table, node.left_table],
            "rows": node.rows,
            "cost": round(_estimate_cost(node), 3),
        }
    raise ValidationError(f"cannot describe node: {type(node).__name__}")


def _sort_key_document(name: str, table: str | None, descending: bool) -> dict[str, object]:
    document = {"column": name, "descending": descending}
    if table is not None:
        document["table"] = table
    return document


def _render_expression(node: object) -> dict[str, object]:
    if isinstance(node, Column):
        return {"column": node.name} | ({"table": node.table} if node.table else {})
    if isinstance(node, Star):
        return {"star": True}
    if isinstance(node, Literal):
        return {"literal": node.value}
    if isinstance(node, Aggregate):
        return {"aggregate": node.function, "argument": _render_expression(node.argument), "distinct": node.distinct}
    return _render_predicate(node)


def _render_predicate(node: object) -> dict[str, object]:
    if isinstance(node, Comparison):
        return {"comparison": node.operator, "left": _render_expression(node.left), "right": _render_expression(node.right)}
    if isinstance(node, InList):
        return {"in": [_render_expression(value) for value in node.values], "negated": node.negated, "operand": _render_expression(node.operand)}
    if isinstance(node, IsNull):
        return {"isNull": True, "negated": node.negated, "operand": _render_expression(node.operand)}
    if isinstance(node, Not):
        return {"not": _render_predicate(node.operand)}
    if isinstance(node, BoolOp):
        return {node.operator: [_render_predicate(operand) for operand in node.operands]}
    if isinstance(node, Literal):
        return {"literal": node.value}
    return _render_expression(node)


# -- planning ------------------------------------------------------------------------------------
def referenced_columns(node: object) -> set[str]:
    """Every column name an expression mentions (aggregate arguments included)."""
    if isinstance(node, Column):
        return {node.name}
    if isinstance(node, Literal):
        return set()
    if isinstance(node, Aggregate):
        return referenced_columns(node.argument)
    names: set[str] = set()
    for attribute in ("left", "right", "operand"):
        child = getattr(node, attribute, None)
        if child is not None:
            names |= referenced_columns(child)
    for attribute in ("operands", "values"):
        children = getattr(node, attribute, None) or ()
        for child in children:
            names |= referenced_columns(child)
    return names


def referenced_column_nodes(node: object) -> set[Column]:
    """Like `referenced_columns`, but qualified: every Column node an expression mentions."""
    if isinstance(node, Column):
        return {node}
    if isinstance(node, (Literal, Star)):
        return set()
    if isinstance(node, Aggregate):
        return referenced_column_nodes(node.argument)
    found: set[Column] = set()
    for attribute in ("left", "right", "operand"):
        child = getattr(node, attribute, None)
        if child is not None:
            found |= referenced_column_nodes(child)
    for attribute in ("operands", "values"):
        children = getattr(node, attribute, None) or ()
        for child in children:
            found |= referenced_column_nodes(child)
    return found


def estimate_selectivity(predicate: object, info: TableInfo) -> float:
    if predicate is None:
        return 1.0
    if isinstance(predicate, BoolOp):
        if predicate.operator == "and":
            value = 1.0
            for operand in predicate.operands:
                value *= estimate_selectivity(operand, info)
            return max(value, 0.0)
        value = 1.0
        for operand in predicate.operands:
            value *= 1.0 - estimate_selectivity(operand, info)
        return min(max(1.0 - value, 0.0), 1.0)
    if isinstance(predicate, Not):
        return 1.0 - estimate_selectivity(predicate.operand, info)
    if isinstance(predicate, IsNull):
        return DEFAULT_IS_NULL
    if isinstance(predicate, InList):
        base = min(DEFAULT_IN * len(predicate.values), 1.0) if predicate.values else 0.0
        return (1.0 - base) if predicate.negated else base
    if isinstance(predicate, Comparison):
        column = predicate.left if isinstance(predicate.left, Column) else predicate.right
        if isinstance(column, Column):
            distinct = info.distinct.get(column.name)
            if predicate.operator == "=" and distinct:
                return min(1.0, 1.0 / distinct)
        return DEFAULT_EQUALITY if predicate.operator == "=" else DEFAULT_RANGE
    return DEFAULT_EQUALITY


def _pinned_value(predicate: object) -> tuple[str, object] | None:
    """A comparison of an indexed column to a literal -- what an index scan needs."""
    if not isinstance(predicate, Comparison) or predicate.operator != "=":
        return None
    if isinstance(predicate.left, Column) and isinstance(predicate.right, Literal):
        return predicate.left.name, predicate.right.value
    if isinstance(predicate.right, Column) and isinstance(predicate.left, Literal):
        return predicate.right.name, predicate.left.value
    return None


def _split_conjuncts(predicate: object) -> list[object]:
    if isinstance(predicate, BoolOp) and predicate.operator == "and":
        parts: list[object] = []
        for operand in predicate.operands:
            parts.extend(_split_conjuncts(operand))
        return parts
    return [predicate]


def _choose_scan(table: str, info: TableInfo, predicate: object, columns: tuple[str, ...], notes: list[str]) -> object:
    """Cost-based scan choice: an index scan only when it is actually cheaper."""
    full = FullScan(table, columns, info.rows)
    full_cost = INDEX_COST * 0 + SCAN_COST_PER_ROW * info.rows
    best: object = full
    best_cost = full_cost
    for conjunct in _split_conjuncts(predicate) if predicate is not None else []:
        pinned = _pinned_value(conjunct)
        if pinned is None:
            continue
        column, value = pinned
        if column not in info.indexes:
            continue
        selectivity = estimate_selectivity(conjunct, info)
        rows = max(1, int(info.rows * selectivity))
        cost = INDEX_COST + SCAN_COST_PER_ROW * rows
        if cost < best_cost:
            best = IndexScan(table, column, value, columns, rows)
            best_cost = cost
            notes.append(f"index scan on {table}.{column} (estimated {rows} of {info.rows} rows)")
    return best


def plan(statement: Select, catalog: Catalog) -> Plan:
    if statement.joins:
        return _plan_join(statement, catalog)

    info = catalog.get(statement.table)
    notes: list[str] = []
    _check_columns(statement, info)

    has_aggregate = any(isinstance(item.expression, Aggregate) for item in statement.projections)
    if has_aggregate and not statement.group_by:
        notes.append("global aggregate: no GROUP BY, so every row folds into one group")

    scan_columns = _columns_to_read(statement, info, notes)
    node: object = _choose_scan(statement.table, info, statement.where, scan_columns, notes)
    rows = int(getattr(node, "rows"))

    if statement.where is not None:
        consumed: tuple[str, object] | None = None
        if isinstance(node, IndexScan):
            consumed = (node.column, node.value)
            notes.append(f"predicate pushdown: '{node.column} = {node.value!r}' is answered by the index")
        pending: list[object] = []
        for conjunct in _split_conjuncts(statement.where):
            if consumed is not None and _pinned_value(conjunct) == consumed:
                continue
            pending.append(conjunct)
        for conjunct in pending:
            rows = max(1, int(rows * estimate_selectivity(conjunct, info)))
            node = PhysicalFilter(node, conjunct, rows)
        if pending:
            notes.append(f"filter: {len(pending)} residual predicate(s) evaluated row by row")

    if has_aggregate or statement.group_by:
        aggregates = tuple(item.expression for item in statement.projections if isinstance(item.expression, Aggregate))
        estimated = 1 if not statement.group_by else max(1, int(rows * 0.5))
        node = PhysicalAggregate(node, tuple(column.name for column in statement.group_by), aggregates, estimated)
        rows = estimated
        notes.append(f"aggregate: {len(statement.group_by)} grouping key(s), {len(aggregates)} aggregate(s)")

    node = PhysicalProject(node, statement.projections)
    if statement.order_by:
        node = PhysicalSort(node, tuple(_sort_key(key) for key in statement.order_by))
        notes.append("sort: exhaustive sort of the projected rows")
    if statement.limit is not None:
        rows = min(rows, statement.limit)
        node = PhysicalLimit(node, statement.limit)
        notes.append(f"limit: at most {statement.limit} row(s) leave the plan")

    return Plan(
        statement=statement,
        logical=_build_logical(statement, scan_columns),
        physical=node,
        estimated_rows=rows,
        estimated_cost=_estimate_cost(node),
        notes=tuple(notes),
    )


def _check_columns(statement: Select, info: TableInfo) -> None:
    expressions: list[tuple[str, object]] = [(f"projection {index + 1}", item.expression) for index, item in enumerate(statement.projections)]
    if statement.where is not None:
        expressions.append(("WHERE", statement.where))
    expressions.extend((f"GROUP BY {column.name}", column) for column in statement.group_by)
    expressions.extend((f"ORDER BY {key.column.name}", key.column) for key in statement.order_by)
    for where, node in expressions:
        for name in sorted(referenced_columns(node)):
            if name not in info.columns:
                raise PlanError(f"unknown column: {name}", in_clause=where, table=statement.table, known=list(info.columns))


def _columns_to_read(statement: Select, info: TableInfo, notes: list[str]) -> tuple[str, ...]:
    needed: set[str] = set()
    for projection in statement.projections:
        if isinstance(projection.expression, Star):
            needed |= set(info.columns)
        needed |= referenced_columns(projection.expression)
    needed |= referenced_columns(statement.where)
    needed |= {column.name for column in statement.group_by}
    needed |= {key.column.name for key in statement.order_by}
    columns = tuple(column for column in info.columns if column in needed)
    if len(columns) != len(info.columns):
        notes.append(f"projection pruning: scan reads {len(columns)} of {len(info.columns)} columns")
    return columns


def _build_logical(statement: Select, scan_columns: tuple[str, ...]) -> object:
    node: object = LogicalScan(statement.table, scan_columns)
    if statement.where is not None:
        node = LogicalFilter(node, statement.where)
    has_aggregate = any(isinstance(item.expression, Aggregate) for item in statement.projections)
    if has_aggregate or statement.group_by:
        aggregates = tuple(item.expression for item in statement.projections if isinstance(item.expression, Aggregate))
        node = LogicalAggregate(node, tuple(column.name for column in statement.group_by), aggregates)
    node = LogicalProject(node, statement.projections)
    if statement.order_by:
        node = LogicalSort(node, tuple((key.column.name, key.descending) for key in statement.order_by))
    if statement.limit is not None:
        node = LogicalLimit(node, statement.limit)
    return node


# -- join planning -------------------------------------------------------------------------------
def _plan_join(statement: Select, catalog: Catalog) -> Plan:
    if len(statement.joins) > 1:
        raise PlanError("only one INNER JOIN is supported", joins=len(statement.joins))
    join = statement.joins[0]
    if join.table == statement.table:
        raise PlanError(f"self-join is not supported: {statement.table} appears on both sides")
    left_info = catalog.get(statement.table)
    right_info = catalog.get(join.table)
    notes: list[str] = []

    left_key, right_key = _check_join_condition(join, left_info, right_info)
    _check_join_columns(statement, left_info, right_info)

    conjuncts = _split_conjuncts(statement.where) if statement.where is not None else []
    left_predicates, right_predicates, residual = _classify_conjuncts(conjuncts, left_info, right_info)

    left_columns = _side_columns(statement, left_info, left_key, left_predicates, residual, notes)
    right_columns = _side_columns(statement, right_info, right_key, right_predicates, residual, notes)
    if left_predicates:
        notes.append(f"predicate pushdown: {len(left_predicates)} WHERE conjunct(s) moved into {left_info.name}")
    if right_predicates:
        notes.append(f"predicate pushdown: {len(right_predicates)} WHERE conjunct(s) moved into {right_info.name}")
    if residual:
        notes.append(f"filter: {len(residual)} conjunct(s) reference both inputs and stay above the join")

    left_predicate = _combine(left_predicates)
    right_predicate = _combine(right_predicates)
    # Side chains evaluate rows local to one table (plain column names), so pushed predicates are
    # localized; everything above the join runs on rows keyed "table.column" and is qualified.
    left_chain, left_rows = _build_side_chain(left_info, _localize(left_predicate, left_info), left_columns, notes)
    right_chain, right_rows = _build_side_chain(right_info, _localize(right_predicate, right_info), right_columns, notes)

    left_distinct = _filtered_distinct(left_info, left_key, left_rows, left_predicate)
    right_distinct = _filtered_distinct(right_info, right_key, right_rows, right_predicate)
    join_rows = max(0, int(left_rows * right_rows / max(left_distinct, right_distinct)))

    physical = _choose_join(
        left_chain,
        right_chain,
        left_info,
        right_info,
        left_key,
        right_key,
        left_rows,
        right_rows,
        left_distinct,
        right_distinct,
        join_rows,
        tuple(_localize(item, right_info) for item in right_predicates),
        tuple(_localize(item, left_info) for item in left_predicates),
        notes,
    )
    rows = join_rows

    residual_predicate = _qualify(_combine(residual), left_info, right_info)
    if residual_predicate is not None:
        merged = TableInfo(
            name=f"{left_info.name}+{right_info.name}",
            columns=tuple(dict.fromkeys(left_info.columns + right_info.columns)),
            rows=rows,
            distinct={**left_info.distinct, **right_info.distinct},
        )
        rows = max(1, int(rows * estimate_selectivity(residual_predicate, merged)))
        physical = PhysicalFilter(physical, residual_predicate, rows, qualified=True)

    projections = tuple(
        Projection(_qualify(item.expression, left_info, right_info), item.alias) for item in statement.projections
    )
    has_aggregate = any(isinstance(item.expression, Aggregate) for item in projections)
    if has_aggregate or statement.group_by:
        if not statement.group_by and not rows:
            rows = 1  # an aggregate over an empty join still emits one group
        aggregates = tuple(item.expression for item in projections if isinstance(item.expression, Aggregate))
        group_columns = [_qualify(column, left_info, right_info) for column in statement.group_by]
        estimated = 1 if not statement.group_by else max(1, int(rows * 0.5))
        physical = PhysicalAggregate(
            physical,
            tuple(_row_key(column) for column in group_columns),
            aggregates,
            estimated,
            qualified=True,
            group_labels=tuple(column.name for column in group_columns),
        )
        rows = estimated
        notes.append(f"aggregate: {len(statement.group_by)} grouping key(s), {len(aggregates)} aggregate(s)")

    physical = PhysicalProject(physical, projections, qualified=True)
    if statement.order_by:
        physical = PhysicalSort(physical, tuple(_sort_key(key) for key in statement.order_by))
        notes.append("sort: exhaustive sort of the projected rows")
    if statement.limit is not None:
        rows = min(rows, statement.limit)
        physical = PhysicalLimit(physical, statement.limit)
        notes.append(f"limit: at most {statement.limit} row(s) leave the plan")

    logical = _build_join_logical(statement, left_columns, right_columns, left_key, right_key)
    return Plan(
        statement=statement,
        logical=logical,
        physical=physical,
        estimated_rows=rows,
        estimated_cost=_estimate_cost(physical),
        notes=tuple(notes),
    )


def _sort_key(key: OrderKey) -> tuple[str, str | None, bool]:
    return key.column.name, key.column.table, key.descending


def _row_key(column: Column) -> str:
    return f"{column.table}.{column.name}" if column.table is not None else column.name


def _qualify(node: object, left_info: TableInfo, right_info: TableInfo) -> object:
    """Give every Column above a join its owning table (rows are keyed 'table.column' there)."""
    if isinstance(node, Column):
        owner = _resolve_side(node, left_info, right_info, "")
        return Column(node.name, owner)
    if isinstance(node, (Literal, Star)):
        return node
    if isinstance(node, Aggregate):
        return Aggregate(node.function, _qualify(node.argument, left_info, right_info), node.distinct)
    if isinstance(node, Comparison):
        return Comparison(_qualify(node.left, left_info, right_info), node.operator, _qualify(node.right, left_info, right_info))
    if isinstance(node, InList):
        return InList(
            _qualify(node.operand, left_info, right_info),
            tuple(_qualify(value, left_info, right_info) for value in node.values),
            node.negated,
        )
    if isinstance(node, IsNull):
        return IsNull(_qualify(node.operand, left_info, right_info), node.negated)
    if isinstance(node, Not):
        return Not(_qualify(node.operand, left_info, right_info))
    if isinstance(node, BoolOp):
        return BoolOp(node.operator, tuple(_qualify(operand, left_info, right_info) for operand in node.operands))
    return node


def _localize(node: object, info: TableInfo) -> object:
    """Drop table qualification from an expression evaluated against one table's local rows."""
    if node is None:
        return None
    if isinstance(node, Column):
        return Column(node.name)
    if isinstance(node, (Literal, Star)):
        return node
    if isinstance(node, Aggregate):
        return Aggregate(node.function, _localize(node.argument, info), node.distinct)
    if isinstance(node, Comparison):
        return Comparison(_localize(node.left, info), node.operator, _localize(node.right, info))
    if isinstance(node, InList):
        return InList(_localize(node.operand, info), tuple(_localize(value, info) for value in node.values), node.negated)
    if isinstance(node, IsNull):
        return IsNull(_localize(node.operand, info), node.negated)
    if isinstance(node, Not):
        return Not(_localize(node.operand, info))
    if isinstance(node, BoolOp):
        return BoolOp(node.operator, tuple(_localize(operand, info) for operand in node.operands))
    return node


def _check_join_condition(join: JoinClause, left_info: TableInfo, right_info: TableInfo) -> tuple[str, str]:
    on = join.on
    if not isinstance(on, Comparison) or on.operator != "=" or not isinstance(on.left, Column) or not isinstance(on.right, Column):
        raise PlanError("ON must be a single equality between one column from each input")
    left_side = _resolve_side(on.left, left_info, right_info, "ON")
    right_side = _resolve_side(on.right, left_info, right_info, "ON")
    if left_side == right_side:
        raise PlanError("join columns must come from different inputs, one from each table")
    return (on.left.name, on.right.name) if left_side == left_info.name else (on.right.name, on.left.name)


def _resolve_side(column: Column, left_info: TableInfo, right_info: TableInfo, where: str) -> str:
    """Which input a column belongs to; ambiguous/unknown/qualified-unknown are plan errors."""
    if column.table is not None:
        if column.table not in (left_info.name, right_info.name):
            raise PlanError(f"unknown table: {column.table}", in_clause=where, known=[left_info.name, right_info.name])
        info = left_info if column.table == left_info.name else right_info
        if column.name not in info.columns:
            raise PlanError(f"unknown column: {column.table}.{column.name}", in_clause=where, known=list(info.columns))
        return info.name
    owners = [info.name for info in (left_info, right_info) if column.name in info.columns]
    if not owners:
        raise PlanError(
            f"unknown column: {column.name}",
            in_clause=where,
            known=sorted(set(left_info.columns) | set(right_info.columns)),
        )
    if len(owners) == 2:
        raise PlanError(f"ambiguous column: {column.name} (present in both inputs)", in_clause=where)
    return owners[0]


def _check_join_columns(statement: Select, left_info: TableInfo, right_info: TableInfo) -> None:
    expressions: list[tuple[str, object]] = [
        (f"projection {index + 1}", item.expression) for index, item in enumerate(statement.projections)
    ]
    if statement.where is not None:
        expressions.append(("WHERE", statement.where))
    expressions.extend((f"GROUP BY {column.name}", column) for column in statement.group_by)
    expressions.extend((f"ORDER BY {key.column.name}", key.column) for key in statement.order_by)
    for where, expression in expressions:
        for column in referenced_column_nodes(expression):
            _resolve_side(column, left_info, right_info, where)


def _classify_conjuncts(
    conjuncts: list[object], left_info: TableInfo, right_info: TableInfo
) -> tuple[list[object], list[object], list[object]]:
    left: list[object] = []
    right: list[object] = []
    residual: list[object] = []
    for conjunct in conjuncts:
        sides = {
            _resolve_side(column, left_info, right_info, "WHERE")
            for column in referenced_column_nodes(conjunct)
        }
        if not sides:
            residual.append(conjunct)
        elif sides == {left_info.name}:
            left.append(conjunct)
        elif sides == {right_info.name}:
            right.append(conjunct)
        else:
            residual.append(conjunct)
    return left, right, residual


def _side_columns(
    statement: Select,
    info: TableInfo,
    key: str,
    predicates: list[object],
    residual: list[object],
    notes: list[str],
) -> tuple[str, ...]:
    """Columns one input must carry: its join key plus everything above the join that names it.

    Pushed conjuncts are evaluated on this side (so all their columns are read), and cross-side
    residual conjuncts still need this side's columns after the join.
    """
    expressions = [item.expression for item in statement.projections if not isinstance(item.expression, Star)]
    expressions.extend(predicates)
    expressions.extend(residual)
    expressions.extend(statement.group_by)
    expressions.extend(order_key.column for order_key in statement.order_by)

    owned: set[str] = {key}
    if any(isinstance(item.expression, Star) for item in statement.projections):
        owned |= set(info.columns)
    for expression in expressions:
        for column in referenced_column_nodes(expression):
            if column.table == info.name or (column.table is None and column.name in info.columns):
                owned.add(column.name)
    columns = tuple(column for column in info.columns if column in owned)
    if len(columns) != len(info.columns):
        notes.append(f"projection pruning: {info.name} scan reads {len(columns)} of {len(info.columns)} columns")
    return columns


def _combine(conjuncts: list[object]) -> object:
    if not conjuncts:
        return None
    if len(conjuncts) == 1:
        return conjuncts[0]
    return BoolOp("and", tuple(conjuncts))


def _filtered_distinct(info: TableInfo, key: str, filtered_rows: int, predicate: object) -> int:
    """Distinct count of the join key among the rows that survive the pushed predicates.

    Equality predicates pin the key to one value; otherwise the distinct count scales with the
    filtered fraction, never above the base count.
    """
    base = max(1, info.distinct.get(key, max(1, info.rows)))
    fraction = 1.0 if info.rows == 0 else filtered_rows / info.rows
    distinct = max(1, int(base * fraction))
    for conjunct in _split_conjuncts(predicate):
        pinned = _pinned_value(conjunct)
        if pinned is not None and pinned[0] == key:
            return 1
    return min(max(1, filtered_rows), distinct)


def _build_side_chain(
    info: TableInfo, predicate: object, columns: tuple[str, ...], notes: list[str]
) -> tuple[object, int]:
    """Full/index scan plus the pushed filters for one input; returns (chain, filtered rows)."""
    node = _choose_scan(info.name, info, predicate, columns, notes)
    rows = int(getattr(node, "rows"))
    consumed: tuple[str, object] | None = None
    if isinstance(node, IndexScan):
        consumed = (node.column, node.value)
    pending = [
        conjunct
        for conjunct in (_split_conjuncts(predicate) if predicate is not None else [])
        if not (consumed is not None and _pinned_value(conjunct) == consumed)
    ]
    for conjunct in pending:
        rows = max(1, int(rows * estimate_selectivity(conjunct, info)))
        node = PhysicalFilter(node, conjunct, rows)
    return node, rows


def _choose_join(
    left_chain: object,
    right_chain: object,
    left_info: TableInfo,
    right_info: TableInfo,
    left_key: str,
    right_key: str,
    left_rows: int,
    right_rows: int,
    left_distinct: int,
    right_distinct: int,
    join_rows: int,
    right_inner_predicates: tuple[object, ...],
    left_inner_predicates: tuple[object, ...],
    notes: list[str],
) -> object:
    left_cost = _estimate_cost(left_chain)
    right_cost = _estimate_cost(right_chain)

    candidates: list[tuple[str, object, float]] = []
    # Candidate order is the documented tie-break: hash-join first, and within hash the FROM order.
    hash_build_left_cost = (
        left_cost
        + right_cost
        + HASH_BUILD_COST_PER_ROW * left_rows
        + HASH_PROBE_COST_PER_ROW * right_rows
        + JOIN_OUTPUT_COST_PER_ROW * join_rows
    )
    candidates.append((
        f"hash-join building {left_info.name}",
        HashJoin(left_chain, right_chain, left_info.name, right_info.name, left_key, right_key, "left", join_rows),
        hash_build_left_cost,
    ))
    hash_build_right_cost = (
        left_cost
        + right_cost
        + HASH_BUILD_COST_PER_ROW * right_rows
        + HASH_PROBE_COST_PER_ROW * left_rows
        + JOIN_OUTPUT_COST_PER_ROW * join_rows
    )
    candidates.append((
        f"hash-join building {right_info.name}",
        HashJoin(left_chain, right_chain, left_info.name, right_info.name, left_key, right_key, "right", join_rows),
        hash_build_right_cost,
    ))

    if right_key in right_info.indexes:
        matched = left_rows * right_rows / max(1, right_distinct)
        cost = (
            left_cost
            + left_rows * INDEX_COST
            + matched * SCAN_COST_PER_ROW
            + JOIN_OUTPUT_COST_PER_ROW * join_rows
        )
        candidates.append((
            f"index-nested-loop join, {left_info.name} outer / {right_info.name} indexed",
            IndexNestedLoopJoin(
                outer=left_chain,
                left_table=left_info.name,
                right_table=right_info.name,
                left_key=left_key,
                right_key=right_key,
                outer_side="left",
                inner_table=right_info.name,
                inner_columns=_scan_columns(right_chain),
                inner_index_column=right_key,
                inner_predicates=right_inner_predicates,
                lookups=left_rows,
                matched_rows=matched,
                rows=join_rows,
            ),
            cost,
        ))
    if left_key in left_info.indexes:
        matched = right_rows * left_rows / max(1, left_distinct)
        cost = (
            right_cost
            + right_rows * INDEX_COST
            + matched * SCAN_COST_PER_ROW
            + JOIN_OUTPUT_COST_PER_ROW * join_rows
        )
        candidates.append((
            f"index-nested-loop join, {right_info.name} outer / {left_info.name} indexed",
            IndexNestedLoopJoin(
                outer=right_chain,
                left_table=left_info.name,
                right_table=right_info.name,
                left_key=left_key,
                right_key=right_key,
                outer_side="right",
                inner_table=left_info.name,
                inner_columns=_scan_columns(left_chain),
                inner_index_column=left_key,
                inner_predicates=left_inner_predicates,
                lookups=right_rows,
                matched_rows=matched,
                rows=join_rows,
            ),
            cost,
        ))

    label, node, cost = candidates[0]
    for candidate_label, candidate_node, candidate_cost in candidates[1:]:
        if candidate_cost < cost:
            label, node, cost = candidate_label, candidate_node, candidate_cost
    notes.append("join candidates: " + "; ".join(f"{name} ~ {value:.3f}" for name, _, value in candidates))
    notes.append(f"join choice: {label} (estimated {join_rows} output rows)")
    return node


def _scan_columns(chain: object) -> tuple[str, ...]:
    while isinstance(chain, PhysicalFilter):
        chain = chain.input
    return tuple(getattr(chain, "columns", ()))


def _build_join_logical(
    statement: Select,
    left_columns: tuple[str, ...],
    right_columns: tuple[str, ...],
    left_key: str,
    right_key: str,
) -> object:
    left: object = LogicalScan(statement.table, left_columns)
    right: object = LogicalScan(statement.joins[0].table, right_columns)
    node: object = LogicalJoin(left, right, statement.table, statement.joins[0].table, left_key, right_key)
    if statement.where is not None:
        node = LogicalFilter(node, statement.where)
    has_aggregate = any(isinstance(item.expression, Aggregate) for item in statement.projections)
    if has_aggregate or statement.group_by:
        aggregates = tuple(item.expression for item in statement.projections if isinstance(item.expression, Aggregate))
        node = LogicalAggregate(node, tuple(column.name for column in statement.group_by), aggregates)
    node = LogicalProject(node, statement.projections)
    if statement.order_by:
        node = LogicalSort(node, tuple((key.column.name, key.descending) for key in statement.order_by))
    if statement.limit is not None:
        node = LogicalLimit(node, statement.limit)
    return node


def rows_produced(node: object) -> int:
    """How many rows this operator hands upward (used by the cost model, and by tests)."""
    if isinstance(node, (FullScan, IndexScan, PhysicalFilter, PhysicalAggregate)):
        return int(node.rows)
    if isinstance(node, (PhysicalProject, PhysicalSort, PhysicalLimit)):
        return rows_produced(node.input)
    if isinstance(node, (HashJoin, IndexNestedLoopJoin)):
        return int(node.rows)
    raise ValidationError(f"cannot count rows for node: {type(node).__name__}")


def _estimate_cost(node: object) -> float:
    if isinstance(node, FullScan):
        return SCAN_COST_PER_ROW * node.rows
    if isinstance(node, IndexScan):
        return INDEX_COST + SCAN_COST_PER_ROW * node.rows
    if isinstance(node, PhysicalFilter):
        return FILTER_COST_PER_ROW * node.rows + _estimate_cost(node.input)
    if isinstance(node, PhysicalProject):
        return PROJECT_COST_PER_ROW * rows_produced(node.input) + _estimate_cost(node.input)
    if isinstance(node, PhysicalAggregate):
        return AGGREGATE_COST_PER_ROW * rows_produced(node.input) + _estimate_cost(node.input)
    if isinstance(node, PhysicalSort):
        return SORT_COST_PER_ROW * rows_produced(node.input) + _estimate_cost(node.input)
    if isinstance(node, PhysicalLimit):
        return _estimate_cost(node.input)
    if isinstance(node, HashJoin):
        left_cost, right_cost = _estimate_cost(node.left), _estimate_cost(node.right)
        build = rows_produced(node.left) if node.build_side == "left" else rows_produced(node.right)
        probe = rows_produced(node.right) if node.build_side == "left" else rows_produced(node.left)
        return (
            left_cost
            + right_cost
            + HASH_BUILD_COST_PER_ROW * build
            + HASH_PROBE_COST_PER_ROW * probe
            + JOIN_OUTPUT_COST_PER_ROW * node.rows
        )
    if isinstance(node, IndexNestedLoopJoin):
        inner_filter_cost = node.matched_rows * FILTER_COST_PER_ROW * len(node.inner_predicates)
        return (
            _estimate_cost(node.outer)
            + node.lookups * INDEX_COST
            + node.matched_rows * SCAN_COST_PER_ROW
            + inner_filter_cost
            + JOIN_OUTPUT_COST_PER_ROW * node.rows
        )
    raise ValidationError(f"cannot cost node: {type(node).__name__}")


def explain(plan_result: Plan) -> dict[str, object]:
    return plan_result.to_document()


# The extension surface is stated, not implied: this build plans one table or an equality INNER JOIN
# of exactly two, and later tasks grow it (three-plus tables and join reordering, outer joins,
# non-equi joins, index-only scans, block indexes).
EXTENSION_SURFACE = (
    "single-table SELECT, or exactly two tables joined by one equality INNER JOIN",
    "no outer joins, no non-equi joins, no self joins, no three-or-more-table plans",
    "no join ordering beyond the hash build side and one index-nested-loop alternative",
    "no index-only scan, no block-sparse index",
    "statistics come from the caller, not from a catalogue service",
)

"""Command line entry point.

Subcommands (stdout is JSON only; errors are one JSON document on stderr):

  describe   -- capabilities and exit codes
  parse      -- the AST of one statement
  plan       -- logical and physical plan with estimates and the rewrites that were applied
  explain    -- the same plan plus an indented operator tree for humans
  run        -- execute the statement against one or two JSONL tables
  reconcile  -- execute the statement through two different physical plans and compare the results

Table bindings are repeatable: ``--table orders=orders.jsonl``; a bare ``--table orders.jsonl`` keeps
the single-table form working. Indexes follow the same split: ``--index orders.cid`` for a join, a
bare ``--index region`` for one table. Exit codes are part of the contract: 0 success, 2 input/usage
error, 3 a report was produced whose verdict is negative (no rows, or two plans disagreed). `run` and
`reconcile` write output atomically, and an output path that collides with any input is rejected
before anything is read.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
import tempfile
from typing import Any, Sequence

from . import __version__
from .errors import OutputError, SQLPlanError, ValidationError
from .executor import Table, execute
from .parser import parse
from .planner import (
    EXTENSION_SURFACE,
    Catalog,
    HashJoin,
    IndexNestedLoopJoin,
    TableInfo,
    describe_node,
    explain,
    plan,
)

EXIT_OK = 0
EXIT_ERROR = 2
EXIT_NEGATIVE = 3


def canonical(document: dict[str, Any]) -> str:
    return json.dumps(document, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _emit(document: dict[str, Any]) -> None:
    sys.stdout.write(canonical(document) + "\n")


def _read_lines(path: str) -> list[str]:
    if path == "-":
        return sys.stdin.read().splitlines()
    try:
        with open(path, encoding="utf-8") as handle:
            return handle.read().splitlines()
    except OSError as error:
        raise ValidationError(f"cannot read input: {error.strerror or error}", value=path) from error


def _write(path: str | None, lines: Sequence[str]) -> None:
    payload = "".join(f"{line}\n" for line in lines)
    if not path or path == "-":
        sys.stdout.write(payload)
        return
    directory = os.path.dirname(os.path.abspath(path)) or "."
    temporary = None
    try:
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=directory, delete=False, newline="\n") as handle:
            temporary = handle.name
            handle.write(payload)
        os.replace(temporary, path)
    except OSError as error:
        if temporary and os.path.exists(temporary):
            os.unlink(temporary)
        raise OutputError(f"cannot write output: {error.strerror or error}", value=path) from error


def _assert_distinct(inputs: Sequence[str | None], output: str | None) -> None:
    if not output or output == "-":
        return
    target = os.path.abspath(output)
    for source in inputs:
        if source and source != "-" and os.path.abspath(source) == target:
            raise OutputError("output path collides with an input path", value=output)


def _load_rows(path: str) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for number, line in enumerate(_read_lines(path), start=1):
        text = line.strip()
        if not text:
            continue
        try:
            document = json.loads(text)
        except json.JSONDecodeError as error:
            raise ValidationError(f"row {number}: invalid JSON: {error.msg}", line=number) from error
        if not isinstance(document, dict):
            raise ValidationError(f"row {number}: each row must be a JSON object", line=number)
        rows.append(document)
    return rows


def _table_bindings(statement: Any, values: Sequence[str]) -> list[tuple[str, str]]:
    """Resolve repeatable --table values to (name, path) pairs in FROM order.

    A one-table query keeps the baseline contract verbatim: the single value is a path and is never
    split (so a path that happens to contain '=' still opens). Only a join switches to the
    repeatable ``name=path`` form, in which every binding must be well-formed.
    """
    required = [statement.table, *(join.table for join in statement.joins)]
    if len(required) == 1:
        if len(values) != 1:
            raise ValidationError("a one-table query takes exactly one --table path")
        return [(required[0], values[0])]

    bindings: dict[str, str] = {}
    for value in values:
        if "=" not in value:
            raise ValidationError(f"malformed table binding: {value!r} (need 'name=path')", value=value)
        name, path = value.split("=", 1)
        name, path = name.strip(), path.strip()
        if not name or not path:
            raise ValidationError(f"malformed table binding: {value!r} (need 'name=path')", value=value)
        if name in bindings:
            raise ValidationError(f"duplicate table binding: {name}", table=name)
        if name not in required:
            raise ValidationError(f"table binding is not used by the query: {name}", table=name, known=required)
        bindings[name] = path
    missing = [name for name in required if name not in bindings]
    if missing:
        raise ValidationError("missing table binding", tables=missing)
    return [(name, bindings[name]) for name in required]


def _index_specs(statement: Any, raw: Sequence[str], table_names: Sequence[str]) -> dict[str, list[str]]:
    specs: dict[str, list[str]] = {name: [] for name in table_names}
    for value in raw:
        if "." in value:
            table, column = value.split(".", 1)
            if not table or not column:
                raise ValidationError(f"malformed index declaration: {value!r} (need 'table.column')", value=value)
            if table not in specs:
                raise ValidationError(f"index on unknown table: {table}", table=table, known=list(table_names))
        else:
            if len(table_names) != 1:
                raise ValidationError("join indexes must be qualified as 'table.column'", value=value)
            table, column = table_names[0], value
        if column not in specs[table]:
            specs[table].append(column)
    return specs


def _catalog_and_tables(
    bindings: Sequence[tuple[str, str]], indexes: dict[str, list[str]]
) -> tuple[Catalog, dict[str, Table]]:
    catalog = Catalog()
    tables: dict[str, Table] = {}
    for name, path in bindings:
        rows = _load_rows(path)
        columns: list[str] = []
        for row in rows:
            for column in row:
                if column not in columns:
                    columns.append(column)
        distinct = {column: len({row.get(column) for row in rows}) for column in columns}
        catalog.add(
            TableInfo(
                name=name,
                columns=tuple(sorted(columns)),
                rows=len(rows),
                distinct=distinct,
                indexes=tuple(indexes.get(name, [])),
            )
        )
        tables[name] = Table(name=name, columns=tuple(sorted(columns)), rows=[dict(row) for row in rows])
    return catalog, tables


def _prepare(args: argparse.Namespace, *, with_index: bool = True) -> tuple[Any, Catalog, dict[str, Table], list[str]]:
    statement = parse(args.sql)
    bindings = _table_bindings(statement, args.table or [])
    input_paths = [path for _, path in bindings]
    _assert_distinct(input_paths, getattr(args, "output", None))
    raw_indexes = args.index or []
    table_names = [name for name, _ in bindings]
    indexes = _index_specs(statement, raw_indexes if with_index else [], table_names) if with_index else {}
    catalog, tables = _catalog_and_tables(bindings, indexes)
    return statement, catalog, tables, input_paths


# -- commands ------------------------------------------------------------------------------------
def _command_describe(_: argparse.Namespace) -> int:
    _emit(
        {
            "name": "sql-query-planner",
            "version": __version__,
            "subcommands": ["describe", "explain", "parse", "plan", "reconcile", "run"],
            "aggregates": ["avg", "count", "max", "min", "sum"],
            "operators": [
                "filter",
                "full-scan",
                "hash-join",
                "index-nested-loop-join",
                "index-scan",
                "limit",
                "project",
                "sort",
                "aggregate",
            ],
            "statistics": "from the tables themselves: row count and per-column distinct counts; --index declares an index",
            "exitCodes": {"ok": EXIT_OK, "error": EXIT_ERROR, "negativeVerdict": EXIT_NEGATIVE},
            "extensionSurface": list(EXTENSION_SURFACE),
        }
    )
    return EXIT_OK


def _command_parse(args: argparse.Namespace) -> int:
    _emit(parse(args.sql).to_document())
    return EXIT_OK


def _command_plan(args: argparse.Namespace) -> int:
    _, catalog, tables, _ = _prepare(args)
    result = plan(parse(args.sql), catalog)
    _emit(result.to_document())
    return EXIT_OK


def _command_explain(args: argparse.Namespace) -> int:
    _, catalog, _, _ = _prepare(args)
    result = plan(parse(args.sql), catalog)
    document = explain(result)
    document["tree"] = _tree(result.physical)
    _emit(document)
    return EXIT_OK


def _command_run(args: argparse.Namespace) -> int:
    statement, catalog, tables, _ = _prepare(args)
    result = plan(statement, catalog)
    columns, rows = execute(result.physical, tables)
    _write(args.output, [canonical({"columns": columns, "rows": rows, "plan": describe_node(result.physical)["operator"]})])
    return EXIT_OK if rows else EXIT_NEGATIVE


def _join_summary(node: object) -> tuple[str | None, list[str] | None]:
    """The join operator a plan uses and its join order, or (None, None) for a single table."""
    found = _first_join(node)
    if found is None:
        return None, None
    document = describe_node(found)
    return str(document["operator"]), list(document.get("joinOrder", []))


def _first_join(node: object) -> object:
    if isinstance(node, (HashJoin, IndexNestedLoopJoin)):
        return node
    for attribute in ("input", "left", "right", "outer"):
        child = getattr(node, attribute, None)
        if child is not None and hasattr(child, "__dataclass_fields__"):
            found = _first_join(child)
            if found is not None:
                return found
    return None


def _scan_operator(node: object) -> str:
    """The access path actually chosen: the first leaf scan walking the plan.

    Reporting only the root operator made `reconcile` useless: every plan ends in `project`, so two
    plans with different access paths looked identical in the report (the test caught exactly that).
    A join descends through its left/outer input to that input's scan; the join itself is reported
    separately as `joinOperator`.
    """
    for attribute in ("input", "left", "outer", "right"):
        child = getattr(node, attribute, None)
        if child is not None and hasattr(child, "__dataclass_fields__"):
            return _scan_operator(child)
    return str(describe_node(node)["operator"])


def _plan_entry(label: str, chosen: object) -> dict[str, Any]:
    join_operator, join_order = _join_summary(chosen.physical)
    return {
        "catalog": label,
        "estimatedCost": round(chosen.estimated_cost, 3),
        "root": describe_node(chosen.physical)["operator"],
        "accessPath": _scan_operator(chosen.physical),
        "joinOperator": join_operator,
        "joinOrder": join_order,
    }


def _command_reconcile(args: argparse.Namespace) -> int:
    statement = parse(args.sql)
    bindings = _table_bindings(statement, args.table or [])
    _assert_distinct([path for _, path in bindings], args.output)
    table_names = [name for name, _ in bindings]
    indexed_specs = _index_specs(statement, args.index or [], table_names)

    indexed_catalog, tables = _catalog_and_tables(bindings, indexed_specs)
    plain_catalog, _ = _catalog_and_tables(bindings, {})

    chosen = plan(statement, indexed_catalog)
    baseline = plan(statement, plain_catalog)
    first = execute(chosen.physical, tables)
    second = execute(baseline.physical, tables)
    identical = first == second
    report = {
        "sql": args.sql,
        "rows": len(first[1]),
        "identical": identical,
        "plans": [_plan_entry("with-index", chosen), _plan_entry("without-index", baseline)],
    }
    if not identical:
        report["first"] = {"columns": first[0], "rows": first[1]}
        report["second"] = {"columns": second[0], "rows": second[1]}
    _write(args.output, [canonical(report)])
    return EXIT_OK if identical else EXIT_NEGATIVE


def _tree_children(document: dict[str, Any]) -> list[dict[str, Any]]:
    # Binary joins expose left/right; every other node is unary through input. outer/inner duplicate
    # left/right on an index-nested-loop join, so they are deliberately not walked again.
    if isinstance(document.get("left"), dict) and isinstance(document.get("right"), dict):
        return [document["left"], document["right"]]
    child = document.get("input")
    return [child] if isinstance(child, dict) else []


def _node_line(document: dict[str, Any], depth: int) -> str:
    operator = str(document["operator"])
    detail = {
        key: value
        for key, value in document.items()
        if key not in ("operator", "input", "left", "right", "outer", "inner")
    }
    return f"{'  ' * depth}{operator} {canonical(detail) if detail else ''}".rstrip()


def _tree(node: object, depth: int = 0) -> list[str]:
    document = describe_node(node)
    lines = [_node_line(document, depth)]
    for child in _tree_children(document):
        lines.extend(_tree_from_document(child, depth + 1))
    return lines


def _tree_from_document(document: dict[str, Any], depth: int) -> list[str]:
    lines = [_node_line(document, depth)]
    for child in _tree_children(document):
        lines.extend(_tree_from_document(child, depth + 1))
    return lines


def _add_query_arguments(parser: argparse.ArgumentParser) -> None:
    parser.add_argument("--sql", required=True)
    parser.add_argument(
        "--table",
        action="append",
        default=[],
        required=True,
        help="JSONL rows as 'name=path' (repeatable); a bare path works for a one-table query; - is stdin",
    )
    parser.add_argument(
        "--index",
        action="append",
        default=[],
        help="index on 'table.column' (repeatable); a bare column works for a one-table query",
    )


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="sql-query-planner", description="SQL parsing, rewriting and cost-based planning")
    parser.add_argument("--version", action="version", version=f"sql-query-planner {__version__}")
    subparsers = parser.add_subparsers(dest="command", required=True)

    subparsers.add_parser("describe", help="print capabilities as JSON").set_defaults(handler=_command_describe)

    parse_command = subparsers.add_parser("parse", help="print the AST")
    parse_command.add_argument("--sql", required=True)
    parse_command.set_defaults(handler=_command_parse)

    for name, handler in (("plan", _command_plan), ("explain", _command_explain)):
        command = subparsers.add_parser(name, help="print the plan" if name == "plan" else "print the plan and a tree")
        _add_query_arguments(command)
        command.set_defaults(handler=handler)

    run = subparsers.add_parser("run", help="execute the statement")
    _add_query_arguments(run)
    run.add_argument("--output")
    run.set_defaults(handler=_command_run)

    reconcile = subparsers.add_parser("reconcile", help="execute through two plans and compare")
    _add_query_arguments(reconcile)
    reconcile.add_argument("--output")
    reconcile.set_defaults(handler=_command_reconcile)
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        return int(args.handler(args))
    except SQLPlanError as error:
        sys.stderr.write(canonical(error.to_document()) + "\n")
        return EXIT_ERROR


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())

"""Recursive-descent parser for the SELECT subset, producing a small immutable AST.

Grammar (everything is optional except SELECT ... FROM ...):

    select   := SELECT projections FROM table
                [INNER JOIN table ON cond] [WHERE cond]
                [GROUP BY column (',' column)*] [ORDER BY column [ASC|DESC]] [LIMIT number] [';']
    proj     := expr [AS identifier] | '*'
    expr     := aggregate '(' (column | '*') ')' | column | literal
    cond     := or_expr
    or_expr  := and_expr (OR and_expr)*
    and_expr := primary (AND primary)*
    primary  := NOT primary | '(' cond ')' | atom [NOT] IN '(' literal (',' literal)* ')'
                | atom IS [NOT] NULL | atom ('='|'<>'|'<'|'<='|'>'|'>=') atom
    atom     := column | literal
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Sequence

from .errors import ParseError, ValidationError
from .lexer import AGGREGATES, Token, tokenise


# -- AST -----------------------------------------------------------------------------------------
@dataclass(frozen=True, slots=True)
class Literal:
    value: object


@dataclass(frozen=True, slots=True)
class Column:
    name: str
    table: str | None = None


@dataclass(frozen=True, slots=True)
class Star:
    pass


@dataclass(frozen=True, slots=True)
class Aggregate:
    function: str
    argument: Column | Star | Literal
    distinct: bool = False


@dataclass(frozen=True, slots=True)
class Comparison:
    left: object
    operator: str
    right: object


@dataclass(frozen=True, slots=True)
class InList:
    operand: object
    values: tuple[object, ...]
    negated: bool = False


@dataclass(frozen=True, slots=True)
class IsNull:
    operand: object
    negated: bool = False


@dataclass(frozen=True, slots=True)
class Not:
    operand: object


@dataclass(frozen=True, slots=True)
class BoolOp:
    operator: str  # and | or
    operands: tuple[object, ...]


@dataclass(frozen=True, slots=True)
class OrderKey:
    column: Column
    descending: bool = False


@dataclass(frozen=True, slots=True)
class Projection:
    expression: object
    alias: str | None = None


@dataclass(frozen=True, slots=True)
class JoinClause:
    """One INNER JOIN: the right-hand table and its ON predicate (equality once planned)."""

    table: str
    on: object


@dataclass(frozen=True, slots=True)
class Select:
    projections: tuple[Projection, ...]
    table: str
    where: object | None = None
    group_by: tuple[Column, ...] = ()
    order_by: tuple[OrderKey, ...] = ()
    limit: int | None = None
    joins: tuple[JoinClause, ...] = ()

    def to_document(self) -> dict[str, object]:
        document: dict[str, object] = {
            "projections": [_projection(item) for item in self.projections],
            "table": self.table,
        }
        if self.joins:
            document["joins"] = [
                {"type": "inner", "table": join.table, "on": _expression(join.on)} for join in self.joins
            ]
        if self.where is not None:
            document["where"] = _expression(self.where)
        if self.group_by:
            document["groupBy"] = [
                item.name if item.table is None else {"name": item.name, "table": item.table}
                for item in self.group_by
            ]
        if self.order_by:
            document["orderBy"] = [
                {"column": key.column.name, "table": key.column.table, "descending": key.descending}
                if key.column.table is not None
                else {"column": key.column.name, "descending": key.descending}
                for key in self.order_by
            ]
        if self.limit is not None:
            document["limit"] = self.limit
        return document


def _projection(projection: Projection) -> dict[str, object]:
    document = {"expression": _expression(projection.expression)}
    if projection.alias:
        document["alias"] = projection.alias
    return document


def _expression(node: object) -> dict[str, object]:
    if isinstance(node, Literal):
        return {"kind": "literal", "value": node.value}
    if isinstance(node, Column):
        return {"kind": "column", "name": node.name} | ({"table": node.table} if node.table else {})
    if isinstance(node, Star):
        return {"kind": "star"}
    if isinstance(node, Aggregate):
        return {"kind": "aggregate", "function": node.function, "argument": _expression(node.argument), "distinct": node.distinct}
    if isinstance(node, Comparison):
        return {"kind": "comparison", "operator": node.operator, "left": _expression(node.left), "right": _expression(node.right)}
    if isinstance(node, InList):
        return {"kind": "in", "negated": node.negated, "operand": _expression(node.operand), "values": [_expression(value) for value in node.values]}
    if isinstance(node, IsNull):
        return {"kind": "isNull", "negated": node.negated, "operand": _expression(node.operand)}
    if isinstance(node, Not):
        return {"kind": "not", "operand": _expression(node.operand)}
    if isinstance(node, BoolOp):
        return {"kind": node.operator, "operands": [_expression(operand) for operand in node.operands]}
    raise ValidationError(f"cannot render expression: {type(node).__name__}")


# -- parser --------------------------------------------------------------------------------------
class Parser:
    def __init__(self, tokens: Sequence[Token]) -> None:
        self.tokens = list(tokens)
        self.index = 0

    # -- helpers ---------------------------------------------------------------------------------
    @property
    def current(self) -> Token:
        return self.tokens[self.index]

    def advance(self) -> Token:
        token = self.tokens[self.index]
        if token.kind != "eof":
            self.index += 1
        return token

    def fail(self, message: str, token: Token | None = None) -> ParseError:
        where = token or self.current
        return ParseError(message, line=where.line, column=where.column, found=where.text)

    def eat_keyword(self, keyword: str) -> Token | None:
        if self.current.kind == "keyword" and self.current.text == keyword:
            return self.advance()
        return None

    def expect_keyword(self, keyword: str) -> Token:
        token = self.eat_keyword(keyword)
        if token is None:
            raise self.fail(f"expected {keyword.upper()}")
        return token

    def eat_operator(self, operator: str) -> Token | None:
        if self.current.kind == "operator" and self.current.text == operator:
            return self.advance()
        return None

    def expect_operator(self, operator: str) -> Token:
        token = self.eat_operator(operator)
        if token is None:
            raise self.fail(f"expected {operator!r}")
        return token

    def expect_identifier(self) -> str:
        if self.current.kind == "identifier":
            return str(self.advance().text)
        raise self.fail("expected an identifier")

    # -- statement -------------------------------------------------------------------------------
    def parse_statement(self) -> Select:
        self.expect_keyword("select")
        projections = self.parse_projections()
        self.expect_keyword("from")
        table = self.expect_identifier()
        joins = tuple(self.parse_joins())
        where = None
        group_by: tuple[Column, ...] = ()
        order_by: tuple[OrderKey, ...] = ()
        limit: int | None = None
        if self.eat_keyword("where"):
            where = self.parse_condition()
        if self.eat_keyword("group"):
            self.expect_keyword("by")
            group_by = tuple(self.parse_column_group())
        if self.eat_keyword("order"):
            self.expect_keyword("by")
            order_by = tuple(self.parse_order_keys())
        if self.eat_keyword("limit"):
            limit = self.parse_limit()
        self.eat_operator(";")
        if self.current.kind != "eof":
            raise self.fail("unexpected trailing input")
        if not projections:
            raise self.fail("SELECT needs at least one projection", self.tokens[0])
        return Select(
            projections=projections,
            table=table,
            where=where,
            group_by=group_by,
            order_by=order_by,
            limit=limit,
            joins=joins,
        )

    def parse_joins(self) -> list[JoinClause]:
        joins: list[JoinClause] = []
        while self.eat_keyword("inner"):
            self.expect_keyword("join")
            right = self.expect_identifier()
            self.expect_keyword("on")
            on = self.parse_condition()
            joins.append(JoinClause(table=right, on=on))
        return joins

    def parse_projections(self) -> tuple[Projection, ...]:
        items = [self.parse_projection()]
        while self.eat_operator(","):
            items.append(self.parse_projection())
        return tuple(items)

    def parse_projection(self) -> Projection:
        if self.eat_operator("*"):
            return Projection(Star())
        expression = self.parse_value()
        alias = None
        if self.eat_keyword("as"):
            alias = self.expect_identifier()
        else:
            alias = None
        return Projection(expression, alias)

    def parse_column_group(self) -> list[Column]:
        columns = [self.parse_column()]
        while self.eat_operator(","):
            columns.append(self.parse_column())
        return columns

    def parse_order_keys(self) -> list[OrderKey]:
        keys = [self.parse_order_key()]
        while self.eat_operator(","):
            keys.append(self.parse_order_key())
        return keys

    def parse_order_key(self) -> OrderKey:
        column = self.parse_column()
        descending = False
        if self.eat_keyword("desc"):
            descending = True
        else:
            self.eat_keyword("asc")
        return OrderKey(column, descending)

    def parse_limit(self) -> int:
        if self.current.kind != "number" or not isinstance(self.current.value, int):
            raise self.fail("LIMIT expects a non-negative integer")
        value = int(self.advance().value)  # type: ignore[arg-type]
        if value < 0:
            raise self.fail("LIMIT must be non-negative")
        return value

    def parse_column(self) -> Column:
        name = self.expect_identifier()
        table = None
        if self.eat_operator("."):
            table, name = name, self.expect_identifier()
        return Column(name=name, table=table)

    # -- values ----------------------------------------------------------------------------------
    def parse_value(self) -> object:
        if self.current.kind == "keyword" and self.current.text in AGGREGATES:
            return self.parse_aggregate()
        return self.parse_atom()

    def parse_aggregate(self) -> Aggregate:
        function = str(self.advance().text)
        distinct = False
        self.expect_operator("(")
        if self.eat_keyword("distinct"):
            distinct = True
        if self.eat_operator("*"):
            argument: object = Star()
        elif self.current.kind == "number" and isinstance(self.current.value, int) and not distinct:
            argument = Literal(int(self.advance().value))  # type: ignore[arg-type]
        else:
            argument = self.parse_column()
        self.expect_operator(")")
        if function != "count" and isinstance(argument, Star):
            raise self.fail(f"{function.upper()} does not accept '*'")
        return Aggregate(function=function, argument=argument, distinct=distinct)

    def parse_atom(self) -> object:
        token = self.current
        if token.kind == "number":
            self.advance()
            return Literal(token.value)
        if token.kind == "string":
            self.advance()
            return Literal(token.value)
        if token.kind == "identifier":
            return self.parse_column()
        if self.eat_operator("("):
            inner = self.parse_value()
            self.expect_operator(")")
            return inner
        raise self.fail("expected a value")

    # -- conditions ------------------------------------------------------------------------------
    def parse_condition(self) -> object:
        return self.parse_or()

    def parse_or(self) -> object:
        operands = [self.parse_and()]
        while self.eat_keyword("or"):
            operands.append(self.parse_and())
        return operands[0] if len(operands) == 1 else BoolOp("or", tuple(operands))

    def parse_and(self) -> object:
        operands = [self.parse_not()]
        while self.eat_keyword("and"):
            operands.append(self.parse_not())
        return operands[0] if len(operands) == 1 else BoolOp("and", tuple(operands))

    def parse_not(self) -> object:
        if self.eat_keyword("not"):
            return Not(self.parse_not())
        if self.eat_operator("("):
            inner = self.parse_condition()
            self.expect_operator(")")
            return inner
        return self.parse_predicate()

    def parse_predicate(self) -> object:
        operand = self.parse_atom()
        if self.eat_keyword("is"):
            negated = bool(self.eat_keyword("not"))
            self.expect_keyword("null")
            return IsNull(operand, negated)
        negated = bool(self.eat_keyword("not"))
        if self.eat_keyword("in"):
            self.expect_operator("(")
            values = [self.parse_atom()]
            while self.eat_operator(","):
                values.append(self.parse_atom())
            self.expect_operator(")")
            return InList(operand, tuple(values), negated)
        if negated:
            raise self.fail("expected IN after NOT")
        for operator in ("=", "<>", "<", "<=", ">", ">="):
            if self.eat_operator(operator):
                return Comparison(operand, operator, self.parse_atom())
        raise self.fail("expected a comparison operator")


def parse(text: str) -> Select:
    """Parse one SELECT statement."""
    stripped = text.strip()
    if not stripped:
        raise ParseError("empty statement", line=1, column=1)
    return Parser(tokenise(stripped)).parse_statement()

